    divisors = [1, 4, 9, 25, 49]
    counts = [0, 0, 0, 0, 0]

    for number in numbers:
        for i, divisor in enumerate(divisors):
            if number % divisor == 0:
                counts[i] += 1

    for count in counts:
        if count >= 1:
            return False
    return True

N = 1
while True:
    if is_valid(N):
        break
    N += 1

print(N)
